// These upstream files were generated by createrepo_c from a genuine RPM,
// independently of ArtifactWeave's metadata encoder.
func rpmUpstreamFixture(t *testing.T) (manifest, primary []byte, primaryPath string) {
	t.Helper()
	dir := filepath.Join("..", "..", "test", "acceptance", "testdata", "rpm-upstream", "repodata")
	manifest, err := os.ReadFile(filepath.Join(dir, "repomd.xml"))
	if err != nil {
		t.Fatal(err)
	}
	primaryPath, _, err = rpm.DecodeRepomd(manifest, "")
	if err != nil {
		t.Fatal(err)
	}
	primary, err = os.ReadFile(filepath.Join(dir, filepath.Base(primaryPath)))
	if err != nil {
		t.Fatal(err)
	}
	return manifest, primary, primaryPath
}

func TestRPMSourceValidationUsesIndependentUpstreamMetadata(t *testing.T) {
	manifest, primary, primaryPath := rpmUpstreamFixture(t)
	for _, tc := range []struct {
		path string
		body []byte
	}{
		{"repodata/repomd.xml", manifest},
		{primaryPath, primary},
	} {
		q, err := rpmSourceRequest(source.Request{
			Repo:     repo.Config{PackageType: repo.RPM},
			Resource: source.Resource{Path: tc.path, Method: http.MethodGet},
		})
		if err != nil || q.Resource.Kind != source.Metadata ||
			q.Resource.ValidateMetadata == nil || q.Resource.Variant == "" {
			t.Fatalf("%s: missing metadata validation: %v, %+v", tc.path, err, q.Resource)
		}
		validate := q.Resource.ValidateMetadata
		if err := validate(
			t.Context(),
			bytes.NewReader(tc.body),
			int64(len(tc.body)),
			source.MetadataResponse{},
		); err != nil {
			t.Fatalf("%s: genuine upstream metadata rejected: %v", tc.path, err)
		}
		for _, bad := range []struct {
			name string
			body []byte
			size int64
		}{
			{"zero size", tc.body, 0},
			{"declared size exceeds body", tc.body, int64(len(tc.body) + 1)},
			{"corrupt content", append([]byte(nil), tc.body...), int64(len(tc.body))},
		} {
			t.Run(tc.path+"/"+bad.name, func(t *testing.T) {
				if bad.name == "corrupt content" {
					bad.body[0] ^= 0xff
				}
				err := validate(
					t.Context(),
					bytes.NewReader(bad.body),
					bad.size,
					source.MetadataResponse{},
				)
				var failure *source.HTTPError
				if !errors.As(err, &failure) || failure.Status != http.StatusBadGateway ||
					failure.Kind != source.IntegrityFailure {
					t.Fatalf("unsafe upstream metadata was accepted: %v", err)
				}
			})
		}
		q.Resource.Query = "download=1"
		if _, err := rpmSourceRequest(q); !errors.Is(err, source.ErrInvalidRequest) {
			t.Errorf("%s: metadata query allowed: %v", tc.path, err)
		}
	}

	body, err := os.ReadFile(
		filepath.Join(
			"..",
			"format",
			"rpm",
			"testdata",
			"artifactweave-alpha-1.0-1.fc42.noarch.rpm",
		),
	)
	if err != nil {
		t.Fatal(err)
	}
	q, err := rpmSourceRequest(source.Request{Resource: source.Resource{
		Path: "pool/artifactweave-alpha-1.0-1.fc42.noarch.rpm", Method: http.MethodGet,
	}})
	if err != nil || q.Resource.Validate == nil {
		t.Fatalf("missing package validation: %v", err)
	}
	if err := q.Resource.Validate(
		t.Context(),
		bytes.NewReader(body),
		int64(len(body)),
	); err != nil {
		t.Fatalf("genuine upstream RPM rejected: %v", err)
	}
	body[len(body)-1] ^= 0xff
	if err := q.Resource.Validate(
		t.Context(),
		bytes.NewReader(body),
		int64(len(body)),
	); err == nil {
		t.Fatal("corrupt upstream RPM accepted")
	}
	q.Resource.Query = "download=1"
	if _, err := rpmSourceRequest(q); !errors.Is(err, source.ErrInvalidRequest) {
		t.Errorf("RPM package query allowed: %v", err)
	}
}

func TestRPMVirtualMemberGraphRejectsCyclesWrongTypesAndUnavailableSources(t *testing.T) {
	w := newItemWorld(t, false)
	for _, c := range []repo.Config{
		{Key: "rpm-wrong", Class: repo.Local, PackageType: repo.Maven},
		{Key: "rpm-remote", Class: repo.Remote, PackageType: repo.RPM, URL: "https://up.example"},
		{Key: "rpm-missing", Class: repo.Virtual, PackageType: repo.RPM, Repositories: []string{"absent"}},
		{Key: "rpm-cycle", Class: repo.Virtual, PackageType: repo.RPM, Repositories: []string{"rpm-cycle"}},
		{Key: "rpm-mixed", Class: repo.Virtual, PackageType: repo.RPM, Repositories: []string{"absent", "rpm-wrong"}},
		{Key: "rpm-offline", Class: repo.Virtual, PackageType: repo.RPM, Repositories: []string{"rpm-remote"}},
	} {
		if err := w.db.Repos().Create(t.Context(), *repo.Defaults(&c)); err != nil {
			t.Fatal(err)
		}
	}
	p := auth.Principal{Name: "admin", Admin: true}
	acc, err := accessFor(t.Context(), w.db, p)
	if err != nil {
		t.Fatal(err)
	}
	svc := artifactoryService{cfg: Config{Store: w.db, Blobs: w.blobs}}
	for _, tc := range []struct {
		key  string
		want error
	}{
		{"rpm-missing", nil},
		{"rpm-cycle", errRPMVirtualCycle},
		{"rpm-mixed", errRPMMemberType},
		{"rpm-offline", source.ErrUnavailable},
	} {
		c, err := w.db.Repos().Get(t.Context(), tc.key)
		if err != nil {
			t.Fatal(err)
		}
		packages, err := svc.rpmCandidates(t.Context(), w.db, c, "", p, acc, map[string]bool{})
		if !errors.Is(err, tc.want) || (tc.want == nil && len(packages) != 0) {
			t.Errorf("%s: packages=%v error=%v, want %v", tc.key, packages, err, tc.want)
		}
	}
	for _, tc := range []struct {
		path   string
		user   string
		status int
	}{
		{"/artifactory/rpm-missing/repodata/repomd.xml", "admin", http.StatusOK},
		{"/artifactory/rpm-missing/repodata/not-published.xml", "admin", http.StatusNotFound},
		{"/artifactory/rpm-missing/repodata/repomd.xml?download=1", "admin", http.StatusNotFound},
		{"/artifactory/rpm-missing/repodata/repomd.xml", "user", http.StatusForbidden},
		{"/artifactory/rpm-cycle/repodata/repomd.xml", "admin", http.StatusInternalServerError},
		{"/artifactory/rpm-mixed/repodata/repomd.xml", "admin", http.StatusInternalServerError},
	} {
		res := w.do(http.MethodGet, tc.path, tc.user, "")
		if res.Code != tc.status {
			t.Errorf(
				"%s as %s: status %d, want %d: %s",
				tc.path,
				tc.user,
				res.Code,
				tc.status,
				res.Body,
			)
		}
	}
	if _, err := svc.rpmCandidates(
		t.Context(),
		w.db,
		repo.Config{Key: "rpm-cycle"},
		"",
		p,
		acc,
		map[string]bool{"rpm-cycle": true},
	); !errors.Is(
		err,
		errRPMVirtualCycle,
	) {
		t.Errorf("previsited virtual member was accepted: %v", err)
	}
	if _, err := boundedRPMMetadata(
		strings.NewReader(strings.Repeat("x", rpmMetadataLimit+1)),
	); !errors.Is(
		err,
		errRPMMetadataTooLarge,
	) {
		t.Errorf("oversized remote metadata was accepted: %v", err)
	}
	if _, err := svc.rpmMemberBytes(t.Context(), w.db,
		repo.Config{Key: "rpm-other", Class: repo.Virtual, PackageType: repo.RPM},
		"repodata/repomd.xml", p, acc); !errors.Is(err, store.ErrNotFound) {
		t.Errorf("virtual member bytes returned %v", err)
	}
}
